import * as React from 'react';
import Box from '@mui/joy/Box';
import Sheet from '@mui/joy/Sheet';
import Typography from '@mui/joy/Typography';
import IconButton from '@mui/joy/IconButton';
import Tooltip from '@mui/joy/Tooltip';
import CircularProgress from '@mui/joy/CircularProgress';
import LinearProgress from '@mui/joy/LinearProgress';
import Chip from '@mui/joy/Chip';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import ChevronRightIcon from '@mui/icons-material/ChevronRight';
import CheckCircleIcon from '@mui/icons-material/CheckCircle';
import RadioButtonUncheckedIcon from '@mui/icons-material/RadioButtonUnchecked';
import LocalFireDepartmentIcon from '@mui/icons-material/LocalFireDepartment';
import EmojiEventsIcon from '@mui/icons-material/EmojiEvents';
import RefreshIcon from '@mui/icons-material/Refresh';

import { ODb } from '../db';
import {
    Habit, HabitsResult, recentDays, summary, streakNote, monthTicks, cadence, dayTitle,
} from '../habits';
import { useSetting } from '../useSettings';
import { useIsMobile } from '../useMobile';

// A square is small on purpose: eight weeks of them has to sit beside a heading
// without becoming a chart somebody has to study.
const CELL = 9;
const GAP = 2;

// How a day is drawn.
//
// The three states have to be visibly three. A miss is the only one drawn in a
// warning colour - a day inside the habit's own slack is not a failure and
// colouring it as one makes a well-kept habit look like a failing one, which is
// the whole reason the server answers with three states rather than two.
function dayStyle(state: string, isToday: boolean) {
    const base = {
        width: CELL, height: CELL, borderRadius: '2px', flexShrink: 0,
        boxSizing: 'border-box' as const,
    };
    // A missed day has to be as readable as a kept one. `danger.softBg` is
    // very nearly the colour of the page, so a run of misses read as a gap in
    // the data rather than as the thing the tracker most needs to show.
    const look =
        state === 'done' ? { backgroundColor: 'var(--joy-palette-success-solidBg)' }
            : state === 'miss' ? { backgroundColor: 'var(--joy-palette-danger-300)' }
                : { backgroundColor: 'var(--joy-palette-neutral-softBg)', opacity: 0.55 };
    // Today is outlined rather than coloured, so it says "here" without saying
    // anything about how today went - which is not decided yet.
    const now = isToday ? { outline: '1.5px solid var(--joy-palette-primary-solidBg)', outlineOffset: '1px' } : {};
    return { ...base, ...look, ...now };
}

function HabitRow({ habit, days, today, onTick, busy }: {
    habit: Habit; days: number; today: string;
    onTick: (h: Habit) => void; busy: boolean;
}) {
    const window = recentDays(habit.Days, days);
    const note = streakNote(habit);
    const ticks = monthTicks(window);

    const noteColor =
        note.tone === 'best' ? 'warning.plainColor'
            : note.tone === 'good' ? 'success.plainColor'
                : note.tone === 'broken' ? 'text.tertiary'
                    : 'text.tertiary';

    return (
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, py: 0.5, minWidth: 0 }}>
            {/* Tick it off. The whole loop in one click: the server moves the
                repeater on, writes the logbook line, and the square fills. */}
            <Tooltip
                size="sm" enterDelay={400}
                title={habit.DoneToday ? 'Done today' : `Tick off — ${cadence(habit)}`}
            >
                <Box>
                    <IconButton
                        size="sm" variant="plain"
                        color={habit.DoneToday ? 'success' : habit.Due ? 'primary' : 'neutral'}
                        disabled={busy || habit.DoneToday || !habit.DoneKeyword}
                        onClick={() => onTick(habit)}
                        sx={{
                            '--IconButton-size': '26px',
                            // A habit kept today should look kept. Joy greys a
                            // disabled button out, which is right for a control
                            // somebody cannot use and wrong for the one square
                            // of the panel that is meant to feel like a reward.
                            '&.Mui-disabled': habit.DoneToday
                                ? { color: 'var(--joy-palette-success-solidBg)' }
                                : {},
                        }}
                    >
                        {habit.DoneToday
                            ? <CheckCircleIcon sx={{ fontSize: 19 }} />
                            : <RadioButtonUncheckedIcon sx={{ fontSize: 19, opacity: habit.Due ? 1 : 0.45 }} />}
                    </IconButton>
                </Box>
            </Tooltip>

            {/* The name, and what it is asking for. */}
            <Box sx={{ width: 190, flexShrink: 0, minWidth: 0 }}>
                <Typography
                    level="body-sm"
                    sx={{
                        fontWeight: habit.Due ? 'lg' : 'md',
                        color: habit.Missed ? 'danger.plainColor' : 'text.primary',
                        overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
                    }}
                    title={`${habit.Headline} — ${cadence(habit)}`}
                >
                    {habit.Headline}
                </Typography>
            </Box>

            {/* The history. */}
            <Box sx={{ position: 'relative', flexShrink: 0 }}>
                <Box sx={{ display: 'flex', gap: `${GAP}px` }}>
                    {window.map(d => (
                        <Tooltip key={d.d} size="sm" enterDelay={300} title={dayTitle(d)}>
                            <Box sx={dayStyle(d.s, d.d === today)} />
                        </Tooltip>
                    ))}
                </Box>
                {/* One month label under the strip, so a run of squares is
                    anchored to a date rather than being an abstract pattern. */}
                <Box sx={{ position: 'relative', height: 11, mt: '1px' }}>
                    {ticks.map(t => (
                        <Typography
                            key={t.at} level="body-xs"
                            sx={{
                                position: 'absolute', left: t.at * (CELL + GAP), top: 0,
                                fontSize: 9, lineHeight: '11px', color: 'text.tertiary',
                            }}
                        >
                            {t.label}
                        </Typography>
                    ))}
                </Box>
            </Box>

            {/* How it is going. */}
            {/* Beside the strip rather than pushed to the right-hand end of
                the row. The row can be wider than the panel - eight weeks of
                squares is - and `ml: auto` in a scrolling row puts these at the
                end of the *scroll*, which is off the screen. */}
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.75, ml: 1.5, flexShrink: 0 }}>
                <Tooltip
                    size="sm" enterDelay={300}
                    title={habit.Best > 0 ? `Best run: ${habit.Best}` : 'No run yet'}
                >
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.25, minWidth: 74, justifyContent: 'flex-end' }}>
                        {note.tone === 'best'
                            ? <EmojiEventsIcon sx={{ fontSize: 14, color: 'warning.plainColor' }} />
                            : note.tone === 'good'
                                ? <LocalFireDepartmentIcon sx={{ fontSize: 14, color: 'success.plainColor' }} />
                                : null}
                        <Typography level="body-xs" sx={{ color: noteColor, fontWeight: note.tone === 'best' ? 'lg' : 'md' }}>
                            {note.text}
                        </Typography>
                    </Box>
                </Tooltip>
                <Tooltip
                    size="sm" enterDelay={300}
                    title={`${Math.round(habit.Rate * 100)}% of what it asked for since you started`}
                >
                    <Typography
                        level="body-xs"
                        sx={{ fontFamily: 'monospace', color: 'text.tertiary', width: 34, textAlign: 'right' }}
                    >
                        {habit.Total > 0 ? `${Math.round(habit.Rate * 100)}%` : '—'}
                    </Typography>
                </Tooltip>
            </Box>
        </Box>
    );
}

export default function HabitTracker() {
    const [open, setOpen] = useSetting('habitsOpen');
    const [windowDays] = useSetting('habitDays');
    const isMobile = useIsMobile();
    const [data, setData] = React.useState<HabitsResult | null>(null);
    const [busy, setBusy] = React.useState(false);
    const [ticking, setTicking] = React.useState<string>('');
    const [failed, setFailed] = React.useState(false);
    // Whether the first read has come back. Until it has there is nothing
    // honest to draw: a panel that appears while loading and vanishes a moment
    // later is worse for somebody with no habits than never appearing at all.
    const [loaded, setLoaded] = React.useState(false);

    const load = React.useCallback(() => {
        setBusy(true);
        ODb.getHabits(windowDays)
            .then(r => { setData(r && r.Ok ? r : null); setFailed(!(r && r.Ok)); })
            .catch(() => setFailed(true))
            .finally(() => { setBusy(false); setLoaded(true); });
    }, [windowDays]);

    React.useEffect(() => { load(); }, [load]);

    // Ticking one off is POST /status/change, the same write every other client
    // makes. The server moves the repeater on, writes the logbook line, and puts
    // the keyword back to a live state - so the answer to "did that work" is the
    // next read of this endpoint rather than anything guessed at here.
    const tick = async (h: Habit) => {
        if (!h.DoneKeyword) return;
        setTicking(h.Hash);
        try {
            await ODb.changeStatus(h.Hash, h.DoneKeyword);
            load();
        } catch {
            setFailed(true);
        } finally {
            setTicking('');
        }
    };

    const head = summary(data);
    const habits = data?.Habits || [];
    // A phone cannot hold eight weeks of squares beside a heading, so it holds
    // the last three - asked for once at the widest and trimmed here, rather
    // than re-fetched when somebody turns their phone sideways.
    const shown = isMobile ? 21 : windowDays;

    // Nothing to show and nothing wrong: stay out of the way. An empty panel
    // explaining a feature somebody is not using is a strip of the agenda spent
    // on nothing - and one that flashes up during the first read and then
    // disappears is worse, because it looks like something broke.
    if (!loaded && !failed) return null;
    if (!failed && habits.length === 0) return null;

    return (
        <Sheet variant="outlined" sx={{ borderRadius: 'sm', mb: 1.5, px: 1.5, py: 1 }}>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                <IconButton
                    size="sm" variant="plain" color="neutral"
                    onClick={() => setOpen(!open)}
                    sx={{ '--IconButton-size': '22px' }}
                >
                    {open ? <ExpandMoreIcon sx={{ fontSize: 17 }} /> : <ChevronRightIcon sx={{ fontSize: 17 }} />}
                </IconButton>
                <Typography level="title-sm">Habits</Typography>
                <Chip
                    size="sm"
                    variant={head.tone === 'due' ? 'soft' : 'plain'}
                    color={head.tone === 'due' ? 'primary' : head.tone === 'done' ? 'success' : 'neutral'}
                >
                    {head.text}
                </Chip>
                {/* The longest run anybody is currently on. It is the one number
                    worth putting where it is seen without opening anything. */}
                {data && data.BestStreak > 1 && (
                    <Tooltip size="sm" title="The longest run you are currently on">
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.25 }}>
                            <LocalFireDepartmentIcon sx={{ fontSize: 15, color: 'warning.plainColor' }} />
                            <Typography level="body-xs" sx={{ fontWeight: 'lg', color: 'warning.plainColor' }}>
                                {data.BestStreak}
                            </Typography>
                        </Box>
                    </Tooltip>
                )}
                <Box sx={{ ml: 'auto', display: 'flex', alignItems: 'center', gap: 0.5 }}>
                    {busy && <CircularProgress size="sm" sx={{ '--CircularProgress-size': '16px' }} />}
                    <Tooltip size="sm" title="Read it again">
                        <IconButton size="sm" variant="plain" color="neutral" onClick={load} sx={{ '--IconButton-size': '22px' }}>
                            <RefreshIcon sx={{ fontSize: 15 }} />
                        </IconButton>
                    </Tooltip>
                </Box>
            </Box>

            {/* Folded, the panel is one line and a bar. That bar is the whole of
                what somebody not working on their habits right now wants from
                it, and it is why folding is worth having rather than hiding. */}
            {!open && habits.length > 0 && (
                <LinearProgress
                    determinate
                    value={habits.length ? (data!.DoneToday / habits.length) * 100 : 0}
                    color={head.tone === 'done' ? 'success' : 'primary'}
                    sx={{ mt: 0.75, '--LinearProgress-thickness': '4px' }}
                />
            )}

            {open && (
                <Box sx={{ mt: 0.5, overflowX: 'auto' }}>
                    {failed && (
                        <Typography level="body-xs" sx={{ color: 'danger.plainColor', py: 0.5 }}>
                            Could not read your habits.
                        </Typography>
                    )}
                    {habits.map(h => (
                        <HabitRow
                            key={h.Hash} habit={h} days={shown} today={data!.Today}
                            onTick={tick} busy={ticking === h.Hash}
                        />
                    ))}
                </Box>
            )}
        </Sheet>
    );
}
