// The hamburger next to the dark mode button: app settings that live in this
// browser. Each group of settings is a submenu that slides open in place rather
// than a second popup, so it stays usable on a phone.

import * as React from 'react';
import Dropdown from '@mui/joy/Dropdown';
import Menu from '@mui/joy/Menu';
import MenuButton from '@mui/joy/MenuButton';
import MenuItem from '@mui/joy/MenuItem';
import IconButton, { IconButtonProps } from '@mui/joy/IconButton';
import ListItemDecorator from '@mui/joy/ListItemDecorator';
import ListItemContent from '@mui/joy/ListItemContent';
import ListSubheader from '@mui/joy/ListSubheader';
import Divider from '@mui/joy/Divider';
import Typography from '@mui/joy/Typography';
import Box from '@mui/joy/Box';
import { useColorScheme } from '@mui/joy/styles';

import MenuIcon from '@mui/icons-material/Menu';
import PaletteOutlinedIcon from '@mui/icons-material/PaletteOutlined';
import CheckIcon from '@mui/icons-material/Check';
import ChevronRightRoundedIcon from '@mui/icons-material/ChevronRightRounded';
import ChevronLeftRoundedIcon from '@mui/icons-material/ChevronLeftRounded';
import CodeRoundedIcon from '@mui/icons-material/CodeRounded';
import PhoneIphoneRoundedIcon from '@mui/icons-material/PhoneIphoneRounded';

import { ODb } from '../db';
import { useSetting } from '../useSettings';
import { HTML_THEME_AUTO, HTML_THEME_FILE, htmlThemeLabel } from '../settings';
import { ORG_THEMES, ORG_THEME_AUTO, orgTheme } from '../orgtheme';
import { LayoutMode } from '../mobile';
import { useViewportIsNarrow } from '../useMobile';

type Pane = 'root' | 'htmlTheme' | 'orgTheme' | 'layout';

// What the layout choices read as, and what each is for. The hint on "auto" says
// what it currently resolves to, because a reader who has forced one of the
// others should be able to see what they overrode.
const LAYOUT_CHOICES: { value: LayoutMode; label: string; hint?: string }[] = [
    { value: 'auto', label: 'Match the screen' },
    { value: 'mobile', label: 'Phone layout' },
    { value: 'desktop', label: 'Desktop layout' },
];

function layoutLabel(mode: LayoutMode): string {
    return (LAYOUT_CHOICES.find(c => c.value === mode) || { label: mode }).label;
}

export default function SettingsMenu(props: IconButtonProps) {
    const { mode } = useColorScheme();
    const [htmlTheme, setHtmlTheme] = useSetting('htmlTheme');
    const [orgThemeKey, setOrgTheme] = useSetting('orgTheme');
    const [layout, setLayout] = useSetting('layout');
    const narrow = useViewportIsNarrow();
    const [themes, setThemes] = React.useState<string[]>([]);
    const [pane, setPane] = React.useState<Pane>('root');

    // The theme list is whatever stylesheets the server has, asked for once the
    // menu is first opened rather than at startup.
    const loadThemes = React.useCallback(async () => {
        if (themes.length > 0) return;
        const res = await ODb.getHtmlThemes();
        if (res && res.length > 0) setThemes(res);
    }, [themes.length]);

    const choices: { value: string; label: string; hint?: string }[] = [
        { value: HTML_THEME_AUTO, label: 'Match app', hint: mode === 'light' ? 'light' : 'dark' },
        ...themes.map(t => ({ value: t, label: htmlThemeLabel(t) })),
        { value: HTML_THEME_FILE, label: 'As written in the file' },
    ];

    return (
        <Dropdown
            onOpenChange={(_, open) => {
                if (open) {
                    loadThemes();
                } else {
                    setPane('root');
                }
            }}
        >
            <MenuButton
                slots={{ root: IconButton }}
                slotProps={{ root: { variant: 'outlined', color: 'neutral', size: 'sm', ...props } }}
                aria-label="Settings"
            >
                <MenuIcon />
            </MenuButton>
            <Menu size="sm" placement="bottom-end" sx={{ minWidth: 230, maxHeight: '70vh', overflow: 'auto' }}>
                {pane === 'root' && [
                    <ListSubheader key="head" sx={{ fontSize: 'xs' }}>Settings</ListSubheader>,
                    <MenuItem
                        key="htmlTheme"
                        // defaultMuiPrevented is the menu's own way of being
                        // told not to close on this click.
                        onClick={(ev) => { (ev as any).defaultMuiPrevented = true; setPane('htmlTheme'); }}
                    >
                        <ListItemDecorator><PaletteOutlinedIcon /></ListItemDecorator>
                        <ListItemContent>
                            Html theme
                            <Typography level="body-xs" sx={{ display: 'block' }}>
                                {(choices.find(c => c.value === htmlTheme) || { label: htmlTheme }).label}
                            </Typography>
                        </ListItemContent>
                        <ChevronRightRoundedIcon />
                    </MenuItem>,
                    <MenuItem
                        key="orgTheme"
                        onClick={(ev) => { (ev as any).defaultMuiPrevented = true; setPane('orgTheme'); }}
                    >
                        <ListItemDecorator><CodeRoundedIcon /></ListItemDecorator>
                        <ListItemContent>
                            Org source theme
                            <Typography level="body-xs" sx={{ display: 'block' }}>
                                {orgThemeKey === ORG_THEME_AUTO
                                    ? 'Follow light / dark'
                                    : (orgTheme(orgThemeKey)?.label || orgThemeKey)}
                            </Typography>
                        </ListItemContent>
                        <ChevronRightRoundedIcon />
                    </MenuItem>,
                    <MenuItem
                        key="layout"
                        onClick={(ev) => { (ev as any).defaultMuiPrevented = true; setPane('layout'); }}
                    >
                        <ListItemDecorator><PhoneIphoneRoundedIcon /></ListItemDecorator>
                        <ListItemContent>
                            Layout
                            <Typography level="body-xs" sx={{ display: 'block' }}>
                                {layout === 'auto'
                                    ? `Match the screen (${narrow ? 'phone' : 'desktop'})`
                                    : layoutLabel(layout as LayoutMode)}
                            </Typography>
                        </ListItemContent>
                        <ChevronRightRoundedIcon />
                    </MenuItem>,
                ]}

                {pane === 'layout' && [
                    <MenuItem key="back" onClick={(ev) => { (ev as any).defaultMuiPrevented = true; setPane('root'); }}>
                        <ListItemDecorator><ChevronLeftRoundedIcon /></ListItemDecorator>
                        <ListItemContent>Layout</ListItemContent>
                    </MenuItem>,
                    <Divider key="div" />,
                    ...LAYOUT_CHOICES.map(c => (
                        <MenuItem
                            key={c.value}
                            selected={c.value === layout}
                            onClick={() => setLayout(c.value)}
                        >
                            <ListItemDecorator>
                                {c.value === layout ? <CheckIcon /> : null}
                            </ListItemDecorator>
                            <ListItemContent>{c.label}</ListItemContent>
                            {c.value === 'auto' && (
                                <Typography level="body-xs">{narrow ? 'phone' : 'desktop'}</Typography>
                            )}
                        </MenuItem>
                    )),
                ]}

                {pane === 'orgTheme' && [
                    <MenuItem key="back" onClick={(ev) => { (ev as any).defaultMuiPrevented = true; setPane('root'); }}>
                        <ListItemDecorator><ChevronLeftRoundedIcon /></ListItemDecorator>
                        <ListItemContent>Org source theme</ListItemContent>
                    </MenuItem>,
                    <Divider key="div" />,
                    <MenuItem
                        key={ORG_THEME_AUTO}
                        selected={orgThemeKey === ORG_THEME_AUTO}
                        onClick={() => setOrgTheme(ORG_THEME_AUTO)}
                    >
                        <ListItemDecorator>
                            {orgThemeKey === ORG_THEME_AUTO ? <CheckIcon /> : null}
                        </ListItemDecorator>
                        <ListItemContent>Follow light / dark</ListItemContent>
                    </MenuItem>,
                    ...ORG_THEMES.map(t => (
                        <MenuItem
                            key={t.key}
                            selected={t.key === orgThemeKey}
                            onClick={() => setOrgTheme(t.key)}
                        >
                            <ListItemDecorator>
                                {t.key === orgThemeKey ? <CheckIcon /> : null}
                            </ListItemDecorator>
                            <ListItemContent>{t.label}</ListItemContent>
                            {/* A scheme is easier to recognise by its own
                                colours than by its name, so each carries three
                                of them: the ground it is read on and two of its
                                accents. */}
                            <Box sx={{ display: 'flex', gap: '3px', alignItems: 'center', ml: 1 }}>
                                {[t.palette.bg, t.palette.h1, t.palette.verbatim].map((c, i) => (
                                    <Box key={i} sx={{
                                        width: 10, height: 10, borderRadius: '2px',
                                        bgcolor: c, border: '1px solid', borderColor: 'neutral.outlinedBorder',
                                    }} />
                                ))}
                            </Box>
                        </MenuItem>
                    )),
                ]}

                {pane === 'htmlTheme' && [
                    <MenuItem key="back" onClick={(ev) => { (ev as any).defaultMuiPrevented = true; setPane('root'); }}>
                        <ListItemDecorator><ChevronLeftRoundedIcon /></ListItemDecorator>
                        <ListItemContent>Html theme</ListItemContent>
                    </MenuItem>,
                    <Divider key="div" />,
                    ...choices.map(c => (
                        <MenuItem
                            key={c.value}
                            selected={c.value === htmlTheme}
                            onClick={() => setHtmlTheme(c.value)}
                        >
                            <ListItemDecorator>
                                {c.value === htmlTheme ? <CheckIcon /> : null}
                            </ListItemDecorator>
                            <ListItemContent>{c.label}</ListItemContent>
                            {c.hint && <Typography level="body-xs">{c.hint}</Typography>}
                        </MenuItem>
                    )),
                ]}
            </Menu>
        </Dropdown>
    );
}
