// The ambient soundscape: a drone, a solar wind, a note per constellation, and a
// crash when a galaxy is blown apart.
//
// It is off until somebody asks for it, and it cannot be otherwise: a browser
// will not start an AudioContext without a gesture, so the toggle is both the
// switch and the gesture. If it still will not resume - which happens - that is
// reported rather than silently doing nothing.
//
// Everything fades rather than cutting. A drone that stops dead is a noise in
// itself.

import { SCALE } from './constants';

export interface SoundEngine {
    // Turn it on or off. Returns what it now is, which is false when the context
    // could not be started at all.
    toggle(vol: number): Promise<boolean>;
    // A short note tuned to a constellation, when the pointer crosses one.
    blip(hz: number): void;
    // The crash a galaxy makes when it is blown apart.
    supernova(): void;
    // Re-read the volume slider.
    applyVol(vol: number): void;
    readonly on: boolean;
    readonly ctx: AudioContext | null;
    // Shut it down. Called when the tab goes away - a 500ms fade would otherwise
    // be an oscillator left running for the life of the page.
    close(): void;
}

export function createSoundEngine(dead: () => boolean): SoundEngine {
    let AC: AudioContext | null = null;
    let droneGain: GainNode | null = null;
    let echo: DelayNode | null = null;
    let soundOn = false;
    let pingTimer: ReturnType<typeof setTimeout> | null = null;

    function start(): void {
        const Ctor = (window as any).AudioContext || (window as any).webkitAudioContext;
        if (!Ctor) return;
        try {
            AC = new Ctor();
        } catch {
            return;
        }
        const ac = AC as AudioContext;

        droneGain = ac.createGain();
        droneGain.gain.value = 0;
        droneGain.connect(ac.destination);

        // A long delay with a damped feedback loop. This is the whole reason the
        // starmap sounds like space rather than like a synthesiser: every note
        // put into it comes back darker and further away.
        echo = ac.createDelay(3);
        echo.delayTime.value = 0.48;
        const fb = ac.createGain();
        fb.gain.value = 0.5;
        const damp = ac.createBiquadFilter();
        damp.type = 'lowpass';
        damp.frequency.value = 1600;
        echo.connect(damp);
        damp.connect(fb);
        fb.connect(echo);
        const eo = ac.createGain();
        eo.gain.value = 0.7;
        echo.connect(eo);
        eo.connect(droneGain);

        // Two low sines a few cents apart, which is what makes the drone beat
        // slowly instead of sitting still.
        for (const [f, g0] of [[52, 0.055], [55.5, 0.045]]) {
            const o = ac.createOscillator();
            o.type = 'sine';
            o.frequency.value = f;
            const g = ac.createGain();
            g.gain.value = g0;
            o.connect(g);
            g.connect(droneGain);
            o.start();
        }

        // The solar wind: a loop of low-passed noise, band-passed and swept very
        // slowly by an LFO.
        const len = 2 * ac.sampleRate;
        const buf = ac.createBuffer(1, len, ac.sampleRate);
        const ch = buf.getChannelData(0);
        let lp = 0;
        for (let i = 0; i < len; i++) {
            lp = lp * 0.97 + (Math.random() * 2 - 1) * 0.03;
            ch[i] = lp * 3;
        }
        const noise = ac.createBufferSource();
        noise.buffer = buf;
        noise.loop = true;
        const bp = ac.createBiquadFilter();
        bp.type = 'bandpass';
        bp.frequency.value = 420;
        bp.Q.value = 0.7;
        const ng = ac.createGain();
        ng.gain.value = 0.16;
        noise.connect(bp);
        bp.connect(ng);
        ng.connect(droneGain);
        ng.connect(echo);
        const lfo = ac.createOscillator();
        lfo.frequency.value = 0.045;
        const lg = ac.createGain();
        lg.gain.value = 260;
        lfo.connect(lg);
        lg.connect(bp.frequency);
        lfo.start();
        noise.start();

        // A note every few seconds, from a scale, so the drone has something to
        // be under.
        const ping = () => {
            if (dead()) return;
            if (soundOn && ac.state === 'running') {
                const f = SCALE[Math.floor(Math.random() * SCALE.length)] * (Math.random() < 0.3 ? 0.5 : 1);
                const o = ac.createOscillator();
                o.type = 'sine';
                o.frequency.setValueAtTime(f, ac.currentTime);
                o.frequency.exponentialRampToValueAtTime(f * 0.985, ac.currentTime + 2.5);
                const g = ac.createGain();
                g.gain.setValueAtTime(0, ac.currentTime);
                g.gain.linearRampToValueAtTime(0.05, ac.currentTime + 0.06);
                g.gain.exponentialRampToValueAtTime(0.0001, ac.currentTime + 3.5);
                o.connect(g);
                g.connect(droneGain as GainNode);
                g.connect(echo as DelayNode);
                o.start();
                o.stop(ac.currentTime + 3.6);
            }
            pingTimer = setTimeout(ping, 2500 + Math.random() * 5500);
        };
        pingTimer = setTimeout(ping, 1200);
    }

    async function toggle(vol: number): Promise<boolean> {
        if (!AC) start();
        if (!AC) return false;
        if (AC.state !== 'running') {
            try { await AC.resume(); } catch { /* nothing to do about it */ }
        }
        if (AC.state !== 'running') return false;
        soundOn = !soundOn;
        (droneGain as GainNode).gain.setTargetAtTime(soundOn ? 0.9 * vol : 0, AC.currentTime, 1.2);
        return soundOn;
    }

    function applyVol(vol: number): void {
        if (AC && droneGain && soundOn) {
            droneGain.gain.setTargetAtTime(0.9 * vol, AC.currentTime, 0.4);
        }
    }

    function blip(hz: number): void {
        if (!soundOn || !AC || AC.state !== 'running') return;
        const o = AC.createOscillator();
        o.type = 'sine';
        o.frequency.setValueAtTime(hz, AC.currentTime);
        o.frequency.exponentialRampToValueAtTime(hz * 0.97, AC.currentTime + 0.9);
        const g = AC.createGain();
        g.gain.setValueAtTime(0, AC.currentTime);
        g.gain.linearRampToValueAtTime(0.05, AC.currentTime + 0.02);
        g.gain.exponentialRampToValueAtTime(0.0001, AC.currentTime + 1.1);
        o.connect(g);
        g.connect(droneGain as GainNode);
        g.connect(echo as DelayNode);
        o.start();
        o.stop(AC.currentTime + 1.2);
    }

    function supernova(): void {
        if (!soundOn || !AC || AC.state !== 'running') return;
        const ac = AC;
        const len = ac.sampleRate * 1.2;
        const buf = ac.createBuffer(1, len, ac.sampleRate);
        const ch = buf.getChannelData(0);
        for (let i = 0; i < len; i++) {
            ch[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / len, 2.5);
        }
        const src = ac.createBufferSource();
        src.buffer = buf;
        const lp = ac.createBiquadFilter();
        lp.type = 'lowpass';
        lp.frequency.value = 400;
        const g = ac.createGain();
        g.gain.value = 0.5;
        src.connect(lp);
        lp.connect(g);
        g.connect(droneGain as GainNode);
        g.connect(echo as DelayNode);
        src.start();
        // The thud under it, which is most of what makes it land.
        const o = ac.createOscillator();
        o.type = 'sine';
        o.frequency.setValueAtTime(90, ac.currentTime);
        o.frequency.exponentialRampToValueAtTime(28, ac.currentTime + 1.4);
        const og = ac.createGain();
        og.gain.setValueAtTime(0.4, ac.currentTime);
        og.gain.exponentialRampToValueAtTime(0.001, ac.currentTime + 1.6);
        o.connect(og);
        og.connect(droneGain as GainNode);
        o.start();
        o.stop(ac.currentTime + 1.7);
    }

    function close(): void {
        soundOn = false;
        if (pingTimer) clearTimeout(pingTimer);
        pingTimer = null;
        if (AC) {
            try { AC.close(); } catch { /* already gone */ }
        }
        AC = null;
    }

    return {
        toggle,
        blip,
        supernova,
        applyVol,
        close,
        get on() { return soundOn; },
        get ctx() { return AC; },
    };
}
