// Flashcards, drilled the way org-drill drills them.
//
// The server (internal/app/orgs/drill.go, drillcards.go) owns everything that
// is written to a file: the three scheduling algorithms, the DRILL_*
// properties, the SCHEDULED stamp, the leech tag. This module owns the session,
// which org-drill keeps in Emacs and nothing ever writes down:
//
//   - the queues, and which card comes next (org-drill-pop-next-pending-entry);
//   - the "again" pile, where a card failed this session comes back until it
//     is passed;
//   - the limits on items and minutes;
//   - which clozes a card hides this time, and which side it asks
//     (org-drill-card-type-alist), chosen afresh every time it is shown;
//   - the report at the end (org-drill-final-report).
//
// All of it is pure and takes its randomness as an argument, so drill.test.ts
// can pin the orders and the cloze choices that would otherwise only show as
// "the drill felt wrong".

// ── What the server sends ───────────────────────────────────────────────────

export type DrillDeck = {
    name: string;
    description?: string;
    query?: string;
    storedQuery?: string;
    algorithm?: string;
    maxItems?: number;
    maxMinutes?: number;
    countFailed?: boolean;
    failureQuality?: number;
    learnFraction?: number;
    forgettingIndex?: number;
    leechThreshold?: number;
    leechMethod?: string;
    daysBeforeOld?: number;
    overdueFactor?: number;
    cramHours?: number;
    sm5Initial?: number;
    noise?: boolean;
    hideTitles?: boolean;
    typedAnswers?: boolean;
    clozeLengthDots?: boolean;
    lapseOverdue?: boolean;
    theme?: string;
};

export type DrillData = {
    lastInterval: number;
    repeats: number;
    failures: number;
    totalRepeats: number;
    meanQ?: number;
    ease?: number;
};

export type DrillSide = { name: string; title: string; body: string; isCard: boolean };

export type DrillStatus = 'new' | 'failed' | 'overdue' | 'young' | 'old' | 'future' | 'skipped';

export type DrillCard = {
    hash: string;
    file: string;
    line: number;
    name: string;
    title: string;
    tags: string[] | null;
    type: string;
    status: DrillStatus;
    due: number;
    age: number;
    leech: boolean;
    data: DrillData;
    lastQuality: number;
    lastReviewed?: string;
    scheduled?: string;
    weight?: number;
    next: number[];
    body: string;
    clozes: number;
    sides: DrillSide[] | null;
    explain?: string[] | null;
    props?: Record<string, string> | null;
};

export type DrillCounts = {
    new: number; failed: number; overdue: number; young: number; old: number;
    future: number; skipped: number; dueTomorrow: number; total: number;
};

export type DrillCardsReply = {
    ok: boolean;
    msg: string;
    deck: DrillDeck;
    query: string;
    cards: DrillCard[] | null;
    counts: DrillCounts;
    problems?: string[] | null;
    style?: string;
};

export type DrillReviewReply = {
    ok: boolean; msg: string; days: number; scheduled?: string;
    data: DrillData; leech: boolean; failed: boolean;
};

// org-drill's defaults, for showing a deck that leaves a setting out.
export const DECK_DEFAULTS: Required<Omit<DrillDeck, 'name' | 'description' | 'query' | 'storedQuery' | 'theme'>> = {
    algorithm: 'sm5', maxItems: 30, maxMinutes: 20, countFailed: false, failureQuality: 2,
    learnFraction: 0.5, forgettingIndex: 10, leechThreshold: 15, leechMethod: 'skip',
    daysBeforeOld: 10, overdueFactor: 1.2, cramHours: 12, sm5Initial: 4, noise: false,
    hideTitles: false, typedAnswers: false, clozeLengthDots: false, lapseOverdue: false,
};

export function deckSetting<K extends keyof typeof DECK_DEFAULTS>(d: DrillDeck, k: K): (typeof DECK_DEFAULTS)[K] {
    const v = (d as any)[k];
    return (v === undefined || v === null || v === 0 || v === '') ? DECK_DEFAULTS[k] : v;
}

// The ratings, in org-drill's words.
export const QUALITIES: { q: number; label: string; meaning: string }[] = [
    { q: 0, label: 'Abject failure', meaning: 'Completely forgot.' },
    { q: 1, label: 'Failure', meaning: 'Even after seeing the answer, it still took a bit to sink in.' },
    { q: 2, label: 'Near miss', meaning: 'After seeing the answer, you remembered it.' },
    { q: 3, label: 'Hard', meaning: 'It took you awhile, but you finally remembered.' },
    { q: 4, label: 'Good', meaning: 'After a little bit of thought you remembered.' },
    { q: 5, label: 'Excellent', meaning: 'You remembered the item really easily.' },
];

// ── Randomness ──────────────────────────────────────────────────────────────

export type Rng = () => number; // [0, 1), like Math.random

export function randInt(rng: Rng, n: number): number {
    return Math.floor(rng() * n);
}

export function shuffle<T>(xs: T[], rng: Rng): T[] {
    const a = xs.slice();
    for (let i = a.length - 1; i > 0; i--) {
        const j = randInt(rng, i + 1);
        [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
}

// A small seeded generator, for tests and for anyone who wants a session to
// come out the same twice.
export function seeded(seed: number): Rng {
    let s = seed >>> 0;
    return () => {
        s = (s + 0x6d2b79f5) >>> 0;
        let t = s;
        t = Math.imul(t ^ (t >>> 15), t | 1);
        t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
        return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
}

// ── The session ─────────────────────────────────────────────────────────────

export type Session = {
    deck: DrillDeck;
    cram: boolean;
    cards: Record<string, DrillCard>;
    // The queues, by hash. `again` is the cards failed this session.
    failed: string[];
    overdue: string[];
    young: string[];
    fresh: string[]; // org-drill's "new"
    old: string[];
    again: string[];
    done: string[];
    current: string | null;
    // Cards failed at some point this session, for the status letter: one
    // back from the again pile is still F.
    failedHere: Record<string, boolean>;
    qualities: number[];
    start: number;
    // Counted when the session was made, for the report.
    dormant: number;
    dueTomorrow: number;
    overdueAtStart: number;
    scanned: number;
};

const LAPSE_DAYS = 90;

// newSession sorts a deck's cards into org-drill's queues.
export function newSession(reply: DrillCardsReply, cram: boolean, now: number, rng: Rng): Session {
    const deck = reply.deck;
    const s: Session = {
        deck, cram, cards: {}, failed: [], overdue: [], young: [], fresh: [], old: [], again: [],
        done: [], current: null, failedHere: {}, qualities: [], start: now,
        dormant: 0, dueTomorrow: reply.counts?.dueTomorrow || 0, overdueAtStart: 0, scanned: 0,
    };
    const overdue: DrillCard[] = [];
    for (const c of reply.cards || []) {
        s.cards[c.hash] = c;
        s.scanned++;
        switch (c.status) {
            case 'failed': s.failed.push(c.hash); break;
            case 'overdue': overdue.push(c); break;
            case 'young': s.young.push(c.hash); break;
            case 'new': s.fresh.push(c.hash); break;
            case 'old': s.old.push(c.hash); break;
            default: s.dormant++;
        }
    }
    s.overdueAtStart = overdue.length;
    s.overdue = orderOverdue(overdue, !!deck.lapseOverdue, rng).map(c => c.hash);
    return s;
}

// orderOverdue is org-drill-order-overdue-entries: shuffled, then the most
// overdue first; cards so long overdue they count as forgotten go last, the
// oldest first.
export function orderOverdue(cards: DrillCard[], lapse: boolean, rng: Rng): DrillCard[] {
    const limit = lapse ? LAPSE_DAYS : Infinity;
    const fresh = shuffle(cards.filter(c => c.due <= limit), rng);
    // Array.prototype.sort is stable, which is what makes the shuffle count.
    fresh.sort((a, b) => b.due - a.due);
    const lapsed = cards.filter(c => c.due > limit).sort((a, b) => b.age - a.age);
    return fresh.concat(lapsed);
}

export function limitReached(s: Session, now: number): boolean {
    if (s.cram) return false;
    const items = deckSetting(s.deck, 'maxItems');
    const minutes = deckSetting(s.deck, 'maxMinutes');
    const count = s.done.length + (s.deck.countFailed ? s.again.length : 0);
    if (items > 0 && count >= items) return true;
    if (minutes > 0 && (now - s.start) / 1000 > minutes * 60) return true;
    return false;
}

function takeRandom(xs: string[], rng: Rng): string {
    const i = randInt(rng, xs.length);
    return xs.splice(i, 1)[0];
}

// nextCard is org-drill-pop-next-pending-entry. Until a limit is reached:
// cards failed in an earlier session, then overdue ones in order, then young
// ones, then new and old together - new chosen in proportion to how many there
// are. After the limit, and always last, the cards failed this session, which
// keep coming back until they are passed.
export function nextCard(s: Session, now: number, rng: Rng): string | null {
    let h: string | null = null;
    if (!limitReached(s, now)) {
        if (s.failed.length) h = takeRandom(s.failed, rng);
        else if (s.overdue.length) h = s.overdue.shift()!;
        else if (s.young.length) h = takeRandom(s.young, rng);
        else if (s.fresh.length || s.old.length) {
            const pickNew = rng() < s.fresh.length / (s.fresh.length + s.old.length);
            h = takeRandom(pickNew ? s.fresh : s.old, rng);
        }
    }
    if (h === null && s.again.length) h = s.again.shift()!;
    s.current = h;
    return h;
}

// rate records a rating. A failure goes to the back of the again pile, which
// is reshuffled first so failures do not come back in the order they failed.
export function rate(s: Session, hash: string, q: number, rng: Rng) {
    // Cram mode writes nothing and counts nothing, as in org-drill; the
    // again pile still works.
    if (!s.cram) s.qualities.push(q);
    if (q <= deckSetting(s.deck, 'failureQuality')) {
        s.again = shuffle(s.again, rng);
        s.again.push(hash);
        s.failedHere[hash] = true;
    } else {
        s.done.push(hash);
    }
    s.current = null;
}

// skip drops a card from the session without a word written.
export function skip(s: Session) {
    s.current = null;
}

export function pending(s: Session): number {
    return (s.current ? 1 : 0) + s.failed.length + s.overdue.length + s.young.length +
        s.fresh.length + s.old.length + s.again.length;
}

// The status letter org-drill shows before a card: F failed, C cram, N new,
// Y young, o old, ! overdue.
export function statusLetter(s: Session, c: DrillCard): { letter: string; tone: 'new' | 'mature' | 'failed' | 'neutral' } {
    if (s.failedHere[c.hash] || c.status === 'failed') return { letter: 'F', tone: 'failed' };
    if (s.cram) return { letter: 'C', tone: 'neutral' };
    switch (c.status) {
        case 'new': return { letter: 'N', tone: 'new' };
        case 'young': return { letter: 'Y', tone: 'mature' };
        case 'old': return { letter: 'o', tone: 'mature' };
        case 'overdue': return { letter: '!', tone: 'failed' };
    }
    return { letter: '?', tone: 'neutral' };
}

export function counters(s: Session) {
    return {
        done: s.done.length,
        failed: s.again.length + s.failed.length,
        mature: s.young.length + s.old.length + s.overdue.length,
        fresh: s.fresh.length,
    };
}

// The clock, as org-drill draws it: MM:SS, and ++:++ past the hour.
export function clock(ms: number): string {
    const secs = Math.max(0, Math.floor(ms / 1000));
    if (secs >= 3600) return '++:++';
    const m = Math.floor(secs / 60), sec = secs % 60;
    return `${String(m).padStart(2, '0')}:${String(sec).padStart(2, '0')}`;
}

// ── What a card asks ────────────────────────────────────────────────────────

export type Presentation = {
    // Cloze numbers hidden in the question. Clozes numbered 0 - in the title
    // and in the sides - are always hidden while the question is up.
    hide: Set<number>;
    // The side asked, for two- and many-sided cards; -1 is none.
    side: number;
    // For the card types that write their own question.
    prompt?: string;
    answerHeading?: string;
};

// org-drill-cloze-text-weight: how often the *_firstmore / *_lastmore types
// take their uncommon case.
const CLOZE_WEIGHT = 4;

type HideOpts = { forceHideFirst?: boolean; forceShowFirst?: boolean; forceShowLast?: boolean };

// hideClozes is org-drill-hide-subheadings's cloze half: which of `count`
// clozes to hide when `n` are to be hidden (a negative n: all but -n).
export function hideClozes(count: number, n: number, rng: Rng, o: HideOpts = {}): Set<number> {
    let positions = shuffle(Array.from({ length: count }, (_, i) => i + 1), rng);
    if (o.forceHideFirst) positions = [1, ...positions.filter(p => p !== 1)];
    if (o.forceShowFirst) positions = positions.filter(p => p !== 1);
    if (o.forceShowLast) positions = positions.filter(p => p !== count);
    const want = n < 0 ? count + n : n;
    if (want > count) return new Set();
    return new Set(positions.slice(0, Math.max(0, Math.min(want, positions.length))));
}

function all(count: number): Set<number> {
    return new Set(Array.from({ length: count }, (_, i) => i + 1));
}

const TENSES = ['present', 'past', 'future perfect'];

export function present(c: DrillCard, rng: Rng): Presentation {
    const sides = c.sides || [];
    const k = c.clozes;
    const uncommon = (c.data.totalRepeats + 1) % CLOZE_WEIGHT === 0;
    switch (c.type) {
        case 'twosided':
            return { hide: all(k), side: sides.length ? randInt(rng, Math.min(2, sides.length)) : -1 };
        case 'multisided':
            return { hide: all(k), side: sides.length ? randInt(rng, sides.length) : -1 };
        case 'hide1cloze': case 'multicloze':
            return { hide: hideClozes(k, 1, rng), side: -1 };
        case 'hide2cloze':
            return { hide: hideClozes(k, 2, rng), side: -1 };
        case 'show1cloze':
            return { hide: hideClozes(k, -1, rng), side: -1 };
        case 'show2cloze':
            return { hide: hideClozes(k, -2, rng), side: -1 };
        case 'hidefirst':
            return { hide: k ? new Set([1]) : new Set(), side: -1 };
        case 'hidelast':
            return { hide: k ? new Set([k]) : new Set(), side: -1 };
        case 'hide1_firstmore':
            return {
                hide: uncommon ? hideClozes(k, 1, rng, { forceShowFirst: true }) : (k ? new Set([1]) : new Set()),
                side: -1,
            };
        case 'show1_lastmore':
            return {
                hide: uncommon ? hideClozes(k, -1, rng, { forceHideFirst: true }) : hideClozes(k, -1, rng, { forceShowLast: true }),
                side: -1,
            };
        case 'show1_firstless':
            return {
                hide: uncommon ? hideClozes(k, -1, rng, { forceShowFirst: true }) : hideClozes(k, -1, rng, { forceHideFirst: true }),
                side: -1,
            };
        case 'conjugate': return conjugate(c, rng);
        case 'decline_noun': return declineNoun(c, rng);
        case 'spanish_verb': {
            const r = randInt(rng, 6);
            const want = r % 2 === 0 ? 'infinitive' : 'english';
            const side = sides.findIndex(s => s.name.toLowerCase() === want);
            const tense = TENSES[Math.floor(r / 2)];
            const prompt = r % 2 === 0
                ? `Translate this Spanish verb, and conjugate it for the ${tense} tense.`
                : `For the English verb below, give the Spanish infinitive, and conjugate it for the ${tense} tense.`;
            return { hide: all(k), side, prompt };
        }
    }
    return { hide: all(k), side: -1 };
}

function cap(s: string): string {
    return s ? s[0].toUpperCase() + s.slice(1) : s;
}

function conjugate(c: DrillCard, rng: Rng): Presentation {
    const p = c.props || {};
    const inf = p.VERB_INFINITIVE || c.name, tr = p.VERB_TRANSLATION || '', hint = p.VERB_INFINITIVE_HINT;
    const tense = p.VERB_TENSE, mood = p.VERB_MOOD;
    const form = tense && mood ? `${tense} tense, ${mood} mood` : tense ? `${tense} tense` : mood ? `${mood} mood` : 'the given form';
    const prompt = rng() < 0.5
        ? `Translate the verb\n\n${inf}\n\nand conjugate for the ${form}.`
        : `Give the verb that means\n\n${tr}${hint ? `  [HINT: ${hint}]` : ''}\n\nand conjugate for the ${form}.`;
    const what = [tense, mood].filter(Boolean).map(x => cap(x!)).join(' ');
    return { hide: new Set(), side: -1, prompt, answerHeading: `${what || 'Conjugation'} of ${inf} ==> ${tr}` };
}

function declineNoun(c: DrillCard, rng: Rng): Presentation {
    const p = c.props || {};
    const noun = p.NOUN || c.name, gender = p.NOUN_GENDER || '', tr = p.NOUN_TRANSLATION || '', hint = p.NOUN_HINT;
    const def = p.DECLINE_DEFINITE, plural = p.DECLINE_PLURAL;
    const truthy = (v?: string) => !!v && v !== 'nil' && v !== 'false';
    const forms = (def !== undefined || plural !== undefined)
        ? ` for the ${truthy(def) ? 'definite' : 'indefinite'} ${truthy(plural) ? 'plural' : 'singular'} form`
        : '';
    const prompt = rng() < 0.5
        ? `Translate the noun\n\n${noun} (${gender})\n\nand list its declensions${forms}.`
        : `Give the noun that means\n\n${tr}${hint ? `  [HINT: ${hint}]` : ''}\n\nand list its declensions${forms}.`;
    return { hide: new Set(), side: -1, prompt, answerHeading: `Declensions of ${noun} (${gender}) ==> ${tr}` };
}

// ── Drawing clozes ──────────────────────────────────────────────────────────

const CLOZE_SPAN = /<span class="drill-cloze" data-n="(\d+)" data-hint="([^"]*)" data-len="(\d+)">([\s\S]*?)<\/span>/g;

// clozeHtml rewrites the server's cloze spans for one phase. In the question a
// hidden cloze is `[...]`, or `[hint...]` when it has a hint (shown as written
// when the hint already says `...`); with `dots`, as many dots as the hidden
// text has letters. In the answer every cloze shows its text, marked, and the
// hint is gone.
export function clozeHtml(html: string, hide: Set<number> | 'none', dots = false): string {
    return html.replace(CLOZE_SPAN, (_m, n, hint, len, text) => {
        const num = Number(n);
        const hidden = hide !== 'none' && (num === 0 || hide.has(num));
        // A cloze left showing in the question is plain text, as org-drill
        // draws it unless asked to colour clozes: marking it would say where
        // the answers are. In the answer every cloze is marked.
        if (!hidden) return hide === 'none' ? `<span class="drill-cloze drill-shown">${text}</span>` : text;
        const fill = dots ? '.'.repeat(Math.max(3, Number(len))) : '...';
        const shown = hint
            ? (hint.includes('...') ? `[${hint}]` : `[${hint}${fill}]`)
            : `[${fill}]`;
        return `<span class="drill-cloze drill-hidden">${shown}</span>`;
    });
}

export const CLOZE_CSS = `
.drill-hidden { font-weight: 600; color: #e0a020; white-space: nowrap; }
.drill-shown { background: rgba(224, 160, 32, 0.22); border-radius: 3px; padding: 0 2px; }
`;

// ── The report ──────────────────────────────────────────────────────────────

export type Report = {
    reviewed: number;
    seconds: number;
    percent: Record<number, number>;
    passPercent: number;
    failureQuality: number;
    pending: number;
    pendingAll: number;
    failed: number; overdue: number; fresh: number; young: number; old: number;
    dueTomorrow: number;
    warn: boolean;
    overduePercent: number;
    overdueAtStart: number;
};

// report is org-drill-final-report's numbers.
export function report(s: Session, now: number): Report {
    const n = Math.max(1, s.qualities.length);
    const percent: Record<number, number> = {};
    for (let q = 0; q <= 5; q++) {
        percent[q] = Math.round(100 * s.qualities.filter(x => x === q).length / n);
    }
    const fq = deckSetting(s.deck, 'failureQuality');
    const passed = s.qualities.filter(q => q > fq).length;
    const passPercent = Math.round(100 * passed / n);
    const p = pending(s);
    const fi = deckSetting(s.deck, 'forgettingIndex');
    return {
        reviewed: s.done.length,
        seconds: Math.round((now - s.start) / 1000),
        percent,
        passPercent,
        failureQuality: fq,
        pending: p,
        pendingAll: p + s.dormant,
        failed: s.failed.length + s.again.length,
        overdue: s.overdue.length,
        fresh: s.fresh.length,
        young: s.young.length,
        old: s.old.length,
        dueTomorrow: s.dueTomorrow,
        warn: s.qualities.length > 0 && passPercent < 100 - fi,
        overduePercent: Math.round(100 * s.overdueAtStart / Math.max(1, s.scanned)),
        overdueAtStart: s.overdueAtStart,
    };
}

// The session duration as org-drill writes it, h:mm:ss.
export function duration(secs: number): string {
    const h = Math.floor(secs / 3600), m = Math.floor(secs / 60) % 60, s = secs % 60;
    return `${h}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
}

// days writes an interval for a rating button: "+4 days".
export function days(d: number): string {
    const n = Math.round(d);
    if (n <= 0) return 'again';
    return n === 1 ? '+1 day' : `+${n} days`;
}

// againSession is org-drill-again: the cards still pending, a fresh clock and a
// fresh tally, and no cram.
export function againSession(s: Session, now: number): Session {
    return { ...s, cram: false, done: [], qualities: [], start: now, current: null };
}
